window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-59b98c975e387d17"]={"versions": [{"id": "FIG-59b98c975e387d17", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Pseudocode-Ablaufdiagramm zur Veranschaulichung der Secure-Boot-Erweiterung im internen ROM-Code eines Mikrocontrollers ohne DMA-Unterstützung (Non-DMA Architecture) im Kontext der AUTOSAR Secure Hardware Extensions (SHE). Das Schema beschreibt die CPU-gesteuerte Initialisierung und schrittweise Zuführung des Bootloader-Codes an das kryptografische SHE-Modul vor der Übergabe der Ausführungskontrolle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Instanzen &amp; Rollen</strong>:\n<ul class=\"fig-list\"><li>Host-CPU / ROM-Code: Führt die sequentielle Boot-Routine aus und liest Speicherbereiche softwaregesteuert aus.\n</li><li>SHE (Secure Hardware Extension): Kryptografische Hardware-Einheit, die Befehle zur Integritätsprüfung des Bootloaders entgegennimmt.\n</li></ul>\n</li><li><strong>Konstanten &amp; Adresszeiger</strong>:\n<ul class=\"fig-list\"><li><code>@SHE_BL_SIZE</code>: Speicheradresse, an der die Länge des Bootloaders hinterlegt ist.\n</li><li><code>@SHE_BL_START</code>: Startadresse des Bootloader-Speicherbereichs.\n</li><li><code>ERC_NO_ERROR</code>: Erfolgs-Rückgabewert der SHE-Befehle.\n</li></ul>\n</li><li><strong>Variablen</strong>:\n<ul class=\"fig-list\"><li><code>BL_SIZE</code>: Aufgenommene Bytegröße bzw. Wortanzahl des zu verifizierenden Bootloaders.\n</li><li><code>DATA</code>: Einzelnes aus dem Speicher ausgelesenes Datenelement.\n</li><li><code>i</code>: Zählvariable der Iterationsschleife.\n</li></ul>\n</li><li><strong>Funktionen &amp; SHE-Kommandoschnittstellen</strong>:\n<ul class=\"fig-list\"><li><code>READ_FROM_MEM(address)</code>: Liest Daten an der angegebenen Speicheradresse.\n</li><li><code>CMD_SECURE_BOOT__INIT(BL_SIZE)</code>: Initialisiert die Verifikation des Bootloaders in der SHE unter Angabe der Gesamtgröße.\n</li><li><code>CMD_SECURE_BOOT__UPDATE(DATA)</code>: Führt der SHE sukzessive Datenblöcke zur fortlaufenden Hash- bzw. MAC-Berechnung zu.\n</li><li><code>CMD_SECURE_BOOT__FINALIZE()</code>: Schließt die Integritäts- und Authentizitätsprüfung in der SHE ab.\n</li><li><code>GOTO SHE_BL_START</code>: Sprungbefehl zur Übergabe der CPU-Ausführung an den verifizierten Bootloader.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ausführung von bestehenden CPU-spezifischen Initialisierungsinstruktionen (<code>// Existing CPU specific initialization instructions</code>).\n</li><li>Auslesen der Bootloader-Größe über <code>BL_SIZE = READ_FROM_MEM(@SHE_BL_SIZE)</code>.\n</li><li>Aufruf von <code>CMD_SECURE_BOOT__INIT(BL_SIZE)</code> zur Initialisierung des Verifikationsprozesses in der Hardware-Extension.\n</li><li>Bedingte Verzweigung: Wenn der Rückgabewert gleich <code>ERC_NO_ERROR</code> ist:\n a. Schleifendurchlauf über den Bootloader-Bereich mit <code>FOR (i = 0, i++, i &lt; BL_SIZE)</code>:\n<ul class=\"fig-list\"><li>Auslesen des aktuellen Datenelements via <code>DATA = READ_FROM_MEM(@SHE_BL_START + i)</code>.\n</li><li>Übergabe des Datenelements an die SHE mittels <code>CMD_SECURE_BOOT__UPDATE(DATA)</code>.\n b. Nach Durchlauf der gesamten Größe: Abschluss der Verifikation durch Aufruf von <code>CMD_SECURE_BOOT__FINALIZE()</code>.\n c. Direkter Sprung zur Ausführung des Bootloaders mittels <code>GOTO SHE_BL_START</code>.\n</li></ul>\n</li><li>Schließen des Bedingungsblocks (<code>END IF</code>).\n</li><li>Fallback-Pfad: Falls die Verifikation fehlschlägt oder nicht erfolgreich initialisiert wird, kann an dieser Stelle ein Sprung zur regulären Boot-Position erfolgen (<code>// A jump to the regular boot position can be performed here</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Pseudocode demonstriert das Referenz-Ablaufmodell für Architekturen ohne DMA-Kopplung zwischen Speicher und SHE. Entwickler von primärem Bootcode bzw. ROM-Code müssen sicherstellen, dass die Übergabe sämtlicher Bootloader-Daten an die SHE vollständig und synchron über CPU-Lesezyklen abgewickelt wird, bevor die Verifikation finalisiert wird. Schlägt <code>CMD_SECURE_BOOT__INIT</code> oder die Verifikation fehl, darf kein Sprung nach <code>SHE_BL_START</code> erfolgen; stattdessen ist eine alternative Fehlerbehandlung bzw. der Fallback auf reguläre Boot-Pfade vorzusehen.</p>"}, {"id": "FIG-68ce35463fc78dab", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Pseudocode-Ablaufdiagramm zur Veranschaulichung der Secure-Boot-Erweiterung im internen ROM-Code eines Mikrocontrollers ohne DMA-Unterstützung (Non-DMA Architecture) im Kontext der AUTOSAR Secure Hardware Extensions (SHE). Das Schema beschreibt die CPU-gesteuerte Initialisierung und schrittweise Zuführung des Bootloader-Codes an das kryptografische SHE-Modul vor der Übergabe der Ausführungskontrolle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Instanzen &amp; Rollen</strong>:\n<ul class=\"fig-list\"><li>Host-CPU / ROM-Code: Führt die sequentielle Boot-Routine aus und liest Speicherbereiche softwaregesteuert aus.\n</li><li>SHE (Secure Hardware Extension): Kryptografische Hardware-Einheit, die Befehle zur Integritätsprüfung des Bootloaders entgegennimmt.\n</li></ul>\n</li><li><strong>Konstanten &amp; Adresszeiger</strong>:\n<ul class=\"fig-list\"><li><code>@SHE_BL_SIZE</code>: Speicheradresse, an der die Länge des Bootloaders hinterlegt ist.\n</li><li><code>@SHE_BL_START</code>: Startadresse des Bootloader-Speicherbereichs.\n</li><li><code>ERC_NO_ERROR</code>: Erfolgs-Rückgabewert der SHE-Befehle.\n</li></ul>\n</li><li><strong>Variablen</strong>:\n<ul class=\"fig-list\"><li><code>BL_SIZE</code>: Aufgenommene Bytegröße bzw. Wortanzahl des zu verifizierenden Bootloaders.\n</li><li><code>DATA</code>: Einzelnes aus dem Speicher ausgelesenes Datenelement.\n</li><li><code>i</code>: Zählvariable der Iterationsschleife.\n</li></ul>\n</li><li><strong>Funktionen &amp; SHE-Kommandoschnittstellen</strong>:\n<ul class=\"fig-list\"><li><code>READ_FROM_MEM(address)</code>: Liest Daten an der angegebenen Speicheradresse.\n</li><li><code>CMD_SECURE_BOOT__INIT(BL_SIZE)</code>: Initialisiert die Verifikation des Bootloaders in der SHE unter Angabe der Gesamtgröße.\n</li><li><code>CMD_SECURE_BOOT__UPDATE(DATA)</code>: Führt der SHE sukzessive Datenblöcke zur fortlaufenden Hash- bzw. MAC-Berechnung zu.\n</li><li><code>CMD_SECURE_BOOT__FINALIZE()</code>: Schließt die Integritäts- und Authentizitätsprüfung in der SHE ab.\n</li><li><code>GOTO SHE_BL_START</code>: Sprungbefehl zur Übergabe der CPU-Ausführung an den verifizierten Bootloader.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Ausführung von bestehenden CPU-spezifischen Initialisierungsinstruktionen (<code>// Existing CPU specific initialization instructions</code>).\n</li><li>Auslesen der Bootloader-Größe über <code>BL_SIZE = READ_FROM_MEM(@SHE_BL_SIZE)</code>.\n</li><li>Aufruf von <code>CMD_SECURE_BOOT__INIT(BL_SIZE)</code> zur Initialisierung des Verifikationsprozesses in der Hardware-Extension.\n</li><li>Bedingte Verzweigung: Wenn der Rückgabewert gleich <code>ERC_NO_ERROR</code> ist:\n a. Schleifendurchlauf über den Bootloader-Bereich mit <code>FOR (i = 0, i++, i &lt; BL_SIZE)</code>:\n<ul class=\"fig-list\"><li>Auslesen des aktuellen Datenelements via <code>DATA = READ_FROM_MEM(@SHE_BL_START + i)</code>.\n</li><li>Übergabe des Datenelements an die SHE mittels <code>CMD_SECURE_BOOT__UPDATE(DATA)</code>.\n b. Nach Durchlauf der gesamten Größe: Abschluss der Verifikation durch Aufruf von <code>CMD_SECURE_BOOT__FINALIZE()</code>.\n c. Direkter Sprung zur Ausführung des Bootloaders mittels <code>GOTO SHE_BL_START</code>.\n</li></ul>\n</li><li>Schließen des Bedingungsblocks (<code>END IF</code>).\n</li><li>Fallback-Pfad: Falls die Verifikation fehlschlägt oder nicht erfolgreich initialisiert wird, kann an dieser Stelle ein Sprung zur regulären Boot-Position erfolgen (<code>// A jump to the regular boot position can be performed here</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Pseudocode demonstriert das Referenz-Ablaufmodell für Architekturen ohne DMA-Kopplung zwischen Speicher und SHE. Entwickler von primärem Bootcode bzw. ROM-Code müssen sicherstellen, dass die Übergabe sämtlicher Bootloader-Daten an die SHE vollständig und synchron über CPU-Lesezyklen abgewickelt wird, bevor die Verifikation finalisiert wird. Schlägt <code>CMD_SECURE_BOOT__INIT</code> oder die Verifikation fehl, darf kein Sprung nach <code>SHE_BL_START</code> erfolgen; stattdessen ist eine alternative Fehlerbehandlung bzw. der Fallback auf reguläre Boot-Pfade vorzusehen.</p>"}], "trans": [{"from": "FIG-59b98c975e387d17", "to": "FIG-68ce35463fc78dab", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
